#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

printf '== fse serious harness ==\n'
printf 'repo: %s\n' "$ROOT"
printf 'go: '
go version
printf 'commit: '
git rev-parse --short HEAD
printf '\n'

run() {
  printf '\n== %s ==\n' "$*"
  "$@"
}

run_in() {
  local dir="$1"
  shift
  printf '\n== (cd %s && %s) ==\n' "$dir" "$*"
  (cd "$dir" && "$@")
}

